code.C:
#include <stdio.h>
#include <ctype.h>
int main() {
    char s[1000]; if (!fgets(s, sizeof(s), stdin)) return 0;
    int cnt = 0;
    for (int i = 0; s[i]; i++) if (isupper(s[i])) cnt++;
    printf("%d\n", cnt);
    return 0;
}

