code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextLine()) {
            String s = sc.nextLine();
            int cnt = 0;
            for (char c : s.toCharArray()) if (Character.isUpperCase(c)) cnt++;
            System.out.println(cnt);
        }
    }
}

